import {
  WalletHistoryDetailData,
  WalletHistoryDetailResponseDTO,
} from '~/entities/wallet/api/dtos/wallet-history-detail';
import { generateTitle } from './generate-title';

export const processWalletData = (data: WalletHistoryDetailResponseDTO): WalletHistoryDetailData => {
  if (!data.tbAcnutMastr) {
    throw new Error('No wallet history detail data found');
  }

  const refundTotal = Number(data.tbAcnutMastr?.refundVouchAmt ?? 0) + Number(data.tbAcnutMastr?.refundAmt ?? 0);
  const paymentTotal = Number(data.tbAcnutMastr?.trnscAmt ?? 0) + Number(data.tbAcnutMastr?.vouchAmt ?? 0);
  const title = generateTitle(data.tbAcnutMastr);

  const { tbAcnutMastr, ...rest } = data;
  const newData: WalletHistoryDetailData = {
    ...tbAcnutMastr,
    refundTotal,
    paymentTotal,
    title,
  };
  return newData;
};
