import { z } from 'zod';
import i18n from '~/shared/i18n/i18n';
import { fieldPathMap } from './field-path-map';

// zod의 에러 메시지 커스터마이징
z.setErrorMap((issue, ctx) => {
  if (issue.path) {
    const pathString = issue.path
      .map((p) => {
        const fieldPath = typeof p === 'string' ? p : p.toString();
        const koreanFieldName = fieldPathMap[fieldPath as keyof typeof fieldPathMap] || fieldPath;
        return `[${koreanFieldName}]`;
      })
      .join(', ');

    return { message: `${pathString}이 존재하지 않습니다.` };
  }

  return { message: i18n.t('validation:temporaryErrorOccurred') };
});
