import { useQuery } from '@tanstack/react-query';
import { WalletHistoryDetailResponseDTO } from '~/entities/wallet/api/dtos/wallet-history-detail';
import { walletApi } from '~/entities/wallet/api/wallet-api';
import { CBDCAxiosError } from '~/shared/@types/error';
import { QueryOptions } from '~/shared/@types/query';
import { queries } from '~/shared/api/query-keys';

export type WalletHistoryDetailParams = {
  tbAcnutMastr: {
    acnutno: string;
    trnscId: string;
    vouchId?: string;
  };
};


export const useWalletHistoryDetailQuery = (
  params: WalletHistoryDetailParams,
  options?: QueryOptions<WalletHistoryDetailResponseDTO, CBDCAxiosError>,
) => {
  const shouldFetch = Boolean(params.tbAcnutMastr.acnutno && params.tbAcnutMastr.trnscId);

  const query = useQuery<WalletHistoryDetailResponseDTO, CBDCAxiosError>({
    queryKey: queries.wallet.walletHistoryDetail(params).queryKey,
    queryFn: () => walletApi.getWalletHistoryDetail(params),
    enabled: shouldFetch,
    staleTime: 1000 * 30,
    gcTime: 1000 * 60 * 5,
    refetchOnWindowFocus: 'always',
    refetchOnMount: 'always',
    refetchOnReconnect: 'always',

    ...options,
  });

  return query;
};
