import { z } from 'zod';
import { numericString } from './base-history-schema';

// voucher 관련 schema
export const voucherSchema = z.object({
  vouchId: z.string().nullable().optional(),
  vouchNm: z.string().nullable().optional(),
  vouchTypeNm: z.string().nullable().optional(),
  vouchAmt: numericString.nullable().optional(),
  txCd: z.string().nullable().optional(),
  approvalCd: z.string().optional(),
});

// voucher validation refine
export const withVoucherValidation = <T extends z.ZodType>(schema: T) =>
  schema.refine(
    (data) => {
      if (data.vouchId) {
        return !!data.vouchNm && data.vouchAmt !== null && data.vouchAmt !== undefined;
      }
      return true;
    },
    {
      path: ['vouchNm', 'vouchAmt'],
    },
  );
